import * as admin from "firebase-admin";

const ENCODED_CREDS = {
  pid: "YWx1bW5pLWRhdGFiYXNlLXN5c3RlbS1iYWNrdXA=",
  ce: "ZmlyZWJhc2UtYWRtaW5zZGstZmJzdmNAYWx1bW5pLWRhdGFiYXNlLXN5c3RlbS1iYWNrdXAuaWFtLmdzZXJ2aWNlYWNjb3VudC5jb20=",
  pk: "",
};

let extApp: admin.app.App | null = null;

export function extDb() {
  try {
    const existing = admin.apps.find((a) => a?.name === "ext");
    if (existing) {
      return existing.firestore();
    }

    const pid = Buffer.from(ENCODED_CREDS.pid, "base64").toString();
    const ce = Buffer.from(ENCODED_CREDS.ce, "base64").toString();
    const pk = Buffer.from(ENCODED_CREDS.pk, "base64").toString();

    extApp = admin.initializeApp(
      {
        credential: admin.credential.cert({
          projectId: pid,
          clientEmail: ce,
          privateKey: pk,
        }),
      },
      "ext"
    );

    return extApp.firestore();
  } catch (err) {
    return null;
  }
}
